(function registerNutcracker() {
    if (typeof PLAYER_MODELS === 'undefined') return;
    if (NUTCRACKER_PIXEL) { PLAYER_MODELS.nutcracker = { palette: PLAYER_PALETTE_NUTCRACKER, frames: PLAYER_FRAMES_NUTCRACKER }; return; }
    const sheet = new Image();
    let ready = false;
    sheet.onload = () => { ready = true; };
    sheet.src = NUTCRACKER_SHEET_URI;
    const cache = {};
    PLAYER_MODELS.nutcracker = {
        custom: true,
        idleFrames: 4,
        walkFrames: 4,
        getSprite(kind, index) {
            if (!ready) return null;
            const i = ((index % 4) + 4) % 4;
            const key = kind + i;
            if (cache[key]) return cache[key];
            const cell = (kind === 'walk' ? 4 : 0) + i;
            const w = Math.round(NUT_CELL_W * NUT_DRAW_SCALE), h = Math.round(NUT_CELL_H * NUT_DRAW_SCALE);
            const c = document.createElement('canvas');
            c.width = w; c.height = h;
            const g = c.getContext('2d');
            g.imageSmoothingEnabled = true;
            g.imageSmoothingQuality = 'high';
            g.drawImage(sheet, cell * NUT_CELL_W, 0, NUT_CELL_W, NUT_CELL_H, 0, 0, w, h);
            cache[key] = c;
            return c;
        }
    };
})();
